#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Spike #113: can the pipeline's agents use VS Code's built-in browser tools?
# Usage: spikes/113-browser-tools/wizard.sh [scratch-dir]   (default ~/browser-spike)
# Throwaway: delete spikes/113-browser-tools/ once #113 is settled.

SPIKE_DIR="${1:-$HOME/browser-spike}"
PORT=8080
REPO="SuperEjay/copilot-delivery-pipeline"
TEST_PROMPT="Open http://localhost:$PORT, read the page, type \"hello\" in the Name box, click Go, read the text under it, and take a screenshot."
SERVER_PID=""

# remember KEY VALUE: store a detected value only if none is saved yet, so ask offers it.
remember() { _existing "$1" >/dev/null 2>&1 || write_env "$1" "$2" >/dev/null; }

stop_server() { [[ -n "$SERVER_PID" ]] && kill "$SERVER_PID" 2>/dev/null || true; }

is_wsl() { grep -qi microsoft /proc/version 2>/dev/null; }

# The user settings.json VS Code reads, wherever this machine keeps it.
settings_files() {
  local f
  for f in "$HOME/.config/Code/User/settings.json" \
           "$HOME/Library/Application Support/Code/User/settings.json" \
           /mnt/c/Users/*/AppData/Roaming/Code/User/settings.json; do
    [[ -f "$f" ]] && printf '%s\n' "$f"
  done
  return 0
}

# setting_value <key>: the value set in user settings, or "not set".
setting_value() {
  local f v
  while IFS= read -r f; do
    v=$(grep -oE "\"$1\"[[:space:]]*:[[:space:]]*[a-z]+" "$f" 2>/dev/null | head -n1 | sed -E 's/.*:[[:space:]]*//') || true
    [[ -n "$v" ]] && { printf '%s' "$v"; return; }
  done < <(settings_files)
  printf 'not set (default)'
}

run_wizard() {

TOTAL_STAGES=10
trap stop_server EXIT

banner "Spike #113: VS Code browser tools"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Build the scratch project"
say "A throwaway project at $SPIKE_DIR: a test page, three probe agents, no Playwright."
for t in python3 curl git; do command -v "$t" >/dev/null 2>&1 || { warn "$t is needed."; exit 1; }; done
if [[ -d "$SPIKE_DIR" && ! -f "$SPIKE_DIR/.browser-spike" ]] && [[ -n "$(ls -A "$SPIKE_DIR" 2>/dev/null)" ]]; then
  warn "$SPIKE_DIR exists and isn't a spike project. Pass another folder: $0 <dir>"; exit 1
fi
mkdir -p "$SPIKE_DIR/.github/agents" "$SPIKE_DIR/site"
touch "$SPIKE_DIR/.browser-spike"
[[ -d "$SPIKE_DIR/.git" ]] || git -C "$SPIKE_DIR" init -q
ENV_FILE="$SPIKE_DIR/.spike-results.env"
cat > "$SPIKE_DIR/site/index.html" <<'EOF'
<!doctype html><title>Spike</title>
<input id="name" placeholder="Name"> <button id="go">Go</button>
<p id="out"></p>
<script>go.onclick = () => out.textContent = 'You typed: ' + name.value</script>
EOF
cat > "$SPIKE_DIR/.github/agents/browser-probe.agent.md" <<'EOF'
---
name: browser-probe
description: "Spike #113: drives the integrated browser"
tools: ['read', 'execute', 'openBrowserPage', 'navigatePage', 'readPage', 'screenshotPage', 'clickElement', 'typeInPage', 'runPlaywrightCode']
---
Do exactly what the prompt asks, using the browser tools. Report each tool you called, what it returned (trimmed), and any error word for word. Never install anything.
EOF
cat > "$SPIKE_DIR/.github/agents/browser-probe-set.agent.md" <<'EOF'
---
name: browser-probe-set
description: "Spike #113: same as browser-probe, but names the tool set 'browser'"
tools: ['read', 'execute', 'browser']
---
Do exactly what the prompt asks, using the browser tools. Report each tool you called, what it returned (trimmed), and any error word for word. Never install anything.
EOF
cat > "$SPIKE_DIR/.github/agents/probe-orchestrator.agent.md" <<'EOF'
---
name: probe-orchestrator
description: "Spike #113: runs browser-probe as a subagent, like the pipeline agent does"
tools: ['read', 'agent']
---
Run the browser-probe agent as a subagent with the prompt you're given. Relay its reply word for word. Don't use any browser tool yourself.
EOF
printf '.spike-results.env\nprobe.png\nserver.log\n' > "$SPIKE_DIR/.gitignore"
say "✓ files written"
if curl -fsS "http://localhost:$PORT" >/dev/null 2>&1; then
  warn "Something already answers on port $PORT. Stop it, then re-run."; exit 1
fi
python3 -m http.server "$PORT" --directory "$SPIKE_DIR/site" > "$SPIKE_DIR/server.log" 2>&1 &
SERVER_PID=$!
sleep 1
if curl -fsS "http://localhost:$PORT" | grep -q 'id="go"'; then
  say "✓ test page served at http://localhost:$PORT (stops when the wizard ends)"
else
  warn "The test page didn't start. See $SPIKE_DIR/server.log"; exit 1
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Open it in VS Code"
if command -v code >/dev/null 2>&1; then
  code "$SPIKE_DIR" >/dev/null 2>&1 || true
  say "↗ opened $SPIKE_DIR in VS Code"
else
  step "Open $SPIKE_DIR in VS Code (File → Open Folder)."
fi
is_wsl && step "On WSL: make sure it's a WSL window (bottom-left shows 'WSL')."
step "Fully quit VS Code and reopen it, so the three probe agents load."
step "Sign in to Copilot with the plan you want to test."
pause "Done? Press Enter"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Environment"
say "Detected values are offered as defaults: press Enter to keep, or type over them."
remember R_VSCODE "$( (code --version 2>/dev/null || true) | head -n1 | tr -d '\r')"
if is_wsl; then remember R_OS "Windows + WSL2 ($(uname -r))"
elif [[ "$(uname -s)" == Darwin ]]; then remember R_OS "macOS $(sw_vers -productVersion 2>/dev/null || true)"
else remember R_OS "$(uname -s) $(uname -r)"; fi
remember R_WSL_WINDOW "$(is_wsl && echo yes || echo no)"
remember R_CHATTOOLS "$(setting_value workbench.browser.enableChatTools)"
note "Check Help → About for the version if it's blank."
ask R_VSCODE "VS Code version:";                  write_env R_VSCODE "$R_VSCODE"
ask R_PLAN "Copilot plan (e.g. Pro, Pro+, Business):"; write_env R_PLAN "$R_PLAN"
ask R_OS "OS:";                                   write_env R_OS "$R_OS"
ask R_WSL_WINDOW "WSL window (yes/no):";          write_env R_WSL_WINDOW "$R_WSL_WINDOW"
ask R_CHATTOOLS "workbench.browser.enableChatTools:"; write_env R_CHATTOOLS "$R_CHATTOOLS"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Check 1 · Tool names"
step "In Copilot Chat, pick the agent browser-probe."
step "Open the tools picker in the chat box (Configure Tools)."
step "Are the browser tools (openBrowserPage, clickElement, …) listed and enabled?"
step "Open .github/agents/browser-probe.agent.md: is any tool name underlined as unknown?"
ask R_TOOLS_INDIV "Individual names (ok / unknown: <which>):"; write_env R_TOOLS_INDIV "$R_TOOLS_INDIV"
step "Now pick browser-probe-set and do the same (its file names the 'browser' set)."
ask R_TOOLS_SET "'browser' set (ok / unknown / deprecated warning):"; write_env R_TOOLS_SET "$R_TOOLS_SET"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Check 3 · Direct use"
step "Pick browser-probe and send this prompt:"
printf '\n    %s%s%s\n\n' "$BOLD" "$TEST_PROMPT" "$RESET"
say "It works if the agent reads back: You typed: hello"
ask R_DIRECT "Result (worked / error: …):"; write_env R_DIRECT "$R_DIRECT"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Check 4 · As a subagent (the one that matters most)"
say "The pipeline runs the verifier as a subagent, so this decides live checks in an auto run."
step "Pick probe-orchestrator and send:"
printf '\n    %sRun browser-probe with this prompt: %s%s\n\n' "$BOLD" "$TEST_PROMPT" "$RESET"
step "Did the browser tools work inside the subagent, or did it say they're unavailable?"
ask R_SUBAGENT "Result (worked / tools missing / error: …):"; write_env R_SUBAGENT "$R_SUBAGENT"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Check 5 · Save a screenshot to disk"
rm -f "$SPIKE_DIR/probe.png"
step "Pick browser-probe and send:"
printf "\n    %sUse runPlaywrightCode to run: await page.goto('http://localhost:%s'); await page.screenshot({ path: '%s' })%s\n\n" \
  "$BOLD" "$PORT" "$SPIKE_DIR/probe.png" "$RESET"
pause "When it has replied, press Enter to check for the file"
if [[ -s "$SPIKE_DIR/probe.png" ]]; then
  png="file exists ($(wc -c < "$SPIKE_DIR/probe.png" | tr -d ' ') bytes)"
  say "✓ $png"
  write_env R_PNG "$png"
else
  warn "No $SPIKE_DIR/probe.png."
  ask R_PNG "What did it say? (no file: <error>):"; write_env R_PNG "$R_PNG"
fi
ask R_PW_NEEDED "Did it complain that Playwright isn't installed? (yes/no):"; write_env R_PW_NEEDED "$R_PW_NEEDED"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Check 6 · WSL2"
if [[ "$R_WSL_WINDOW" == yes ]]; then
  say "Check 3 ran in a WSL window: $R_DIRECT"
  step "If it failed: Settings → turn on workbench.browser.enableRemoteProxy, reload the window, run check 3 again."
  ask R_WSL "WSL (worked / worked with enableRemoteProxy / failed: …):"; write_env R_WSL "$R_WSL"
else
  say "Not a WSL window: nothing to do here."
  write_env R_WSL "n/a"
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Check 7 · Cost"
say "Roughly what one live check costs."
step "Look at your Copilot premium-request usage (wherever your plan shows it)."
step "Run check 3 once more and look again."
ask R_COST "Premium requests used by one check 3 (a number, or 'not shown'):"; write_env R_COST "$R_COST"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Check 8 · Copilot Free, and the report"
say "Copilot Free is checked on a Free account. Re-run this wizard there later, or leave it."
ask R_FREE "Free (not yet / worked / not available):"; write_env R_FREE "${R_FREE:-not yet}"
report="$SPIKE_DIR/report.md"
{
  printf 'VS Code: %s · Plan: %s · OS: %s · WSL window: %s · enableChatTools: %s\n' "$R_VSCODE" "$R_PLAN" "$R_OS" "$R_WSL_WINDOW" "$R_CHATTOOLS"
  printf "1 tool names: individual names %s · 'browser' set %s\n" "$R_TOOLS_INDIV" "$R_TOOLS_SET"
  printf '3 direct: %s\n' "$R_DIRECT"
  printf '4 subagent: %s\n' "$R_SUBAGENT"
  printf '5 save PNG: %s · needed Playwright: %s\n' "$R_PNG" "$R_PW_NEEDED"
  printf '6 WSL: %s\n' "$R_WSL"
  printf '7 cost: %s\n' "$R_COST"
  printf '8 Free: %s\n' "$R_FREE"
} > "$report"
printf '\n'; sed 's/^/    /' "$report"; printf '\n'
say "Saved to $report. Paste it back in the Claude session."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  if confirm "Also post it as a comment on $REPO#113?"; then
    { printf 'Spike results (from `spikes/113-browser-tools/wizard.sh`):\n\n```\n'; cat "$report"; printf '```\n'; } \
      | gh issue comment 113 --repo "$REPO" --body-file - >/dev/null && say "✓ posted to #113"
  fi
else
  SKIPPED+=("posting to #113 (gh not logged in): paste $report back instead")
fi

finish
}

run_wizard "$@"; exit
